class ArticleClientSpec extends AnyFlatSpecLike with Matchers {
  "ArticleClient" should "return titles" in {
    val pact = ConsumerPactBuilder.consumer("article-consumer").hasPactWith("ArticlesProvider")
      .given("articles exist").uponReceiving("a request for articles")
      .path("/articles.json").method("GET")
      .willRespondWith().status(200).body("{\"articles\":[{\"title\":\"Intro\"}]}")
      .toPact()
    runConsumerTest(pact, MockProviderConfig.createDefault(), (server: MockServer) => {
      new ArticleClient(server.getUrl).titles() should contain("Intro")
    })
  }
}
